    class ChannelBank(ReadWriteKaitaiStruct):
        """Logical IDs 0x13-0x40, channel bank slots 2-47, 85 channels each from offset 0; slot n
        (ID 0x12 + n - 1) holds channels 85 + (n - 2) * 85 onwards.
        
        .. seealso::
           infamy/DM32-Protocol-Spec 04-MEMORY-LAYOUT.md "Channel bank capacity"
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(Dm32Codeplug.ChannelBank, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.channels = []
            for i in range(85):
                _t_channels = Dm32Codeplug.Channel(self._io, self, self._root)
                try:
                    _t_channels._read()
                finally:
                    self.channels.append(_t_channels)

            self.tail = self._io.read_bytes(15)
            self.tag = self._io.read_u1()
            self._dirty = False


        def _fetch_instances(self):
            pass
            for i in range(len(self.channels)):
                pass
                self.channels[i]._fetch_instances()



        def _write__seq(self, io=None):
            super(Dm32Codeplug.ChannelBank, self)._write__seq(io)
            for i in range(len(self.channels)):
                pass
                self.channels[i]._write__seq(self._io)

            self._io.write_bytes(self.tail)
            self._io.write_u1(self.tag)


        def _check(self):
            if len(self.channels) != 85:
                raise kaitaistruct.ConsistencyError(u"channels", 85, len(self.channels))
            for i in range(len(self.channels)):
                pass
                if self.channels[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"channels", self._root, self.channels[i]._root)
                if self.channels[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"channels", self, self.channels[i]._parent)

            if len(self.tail) != 15:
                raise kaitaistruct.ConsistencyError(u"tail", 15, len(self.tail))
            self._dirty = False


    class ChannelBankFirst(ReadWriteKaitaiStruct):
        """Logical ID 0x12, channel bank slot 1 - 16-byte header with the channel count, then channels 1-84.
        
        .. seealso::
           infamy/DM32-Protocol-Spec 04-MEMORY-LAYOUT.md "Channel Block Structure"
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(Dm32Codeplug.ChannelBankFirst, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.channel_count = self._io.read_u2le()
            self.header_fill = self._io.read_bytes(14)
            self.channels = []
            for i in range(84):
                _t_channels = Dm32Codeplug.Channel(self._io, self, self._root)
                try:
                    _t_channels._read()
                finally:
                    self.channels.append(_t_channels)

            self.tail = self._io.read_bytes(47)
            self.tag = self._io.read_u1()
            self._dirty = False


        def _fetch_instances(self):
            pass
            for i in range(len(self.channels)):
                pass
                self.channels[i]._fetch_instances()



        def _write__seq(self, io=None):
            super(Dm32Codeplug.ChannelBankFirst, self)._write__seq(io)
            self._io.write_u2le(self.channel_count)
            self._io.write_bytes(self.header_fill)
            for i in range(len(self.channels)):
                pass
                self.channels[i]._write__seq(self._io)

            self._io.write_bytes(self.tail)
            self._io.write_u1(self.tag)


        def _check(self):
            if len(self.header_fill) != 14:
                raise kaitaistruct.ConsistencyError(u"header_fill", 14, len(self.header_fill))
            if len(self.channels) != 84:
                raise kaitaistruct.ConsistencyError(u"channels", 84, len(self.channels))
            for i in range(len(self.channels)):
                pass
                if self.channels[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"channels", self._root, self.channels[i]._root)
                if self.channels[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"channels", self, self.channels[i]._parent)

            if len(self.tail) != 47:
                raise kaitaistruct.ConsistencyError(u"tail", 47, len(self.tail))
            self._dirty = False


    class ChannelBankVfo(ReadWriteKaitaiStruct):
        """Logical ID 0x41: the last channel bank slot AND the home of the VFO A / VFO B records at
        0xF9F / 0xFCF (ordinary channel records). The two uses collide: channel records 83 and 84
        of this slot would overlap the VFOs, so this description decodes 83 channels and the VFOs,
        which is what hardware shows.
        
        .. seealso::
           infamy/DM32-Protocol-Spec 05-DATA-STRUCTURES.md "0x41 - VFO A / VFO B Channel Records"
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(Dm32Codeplug.ChannelBankVfo, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.channels = []
            for i in range(83):
                _t_channels = Dm32Codeplug.Channel(self._io, self, self._root)
                try:
                    _t_channels._read()
                finally:
                    self.channels.append(_t_channels)

            self.gap = self._io.read_bytes(15)
            self.vfo_a = Dm32Codeplug.Channel(self._io, self, self._root)
            self.vfo_a._read()
            self.vfo_b = Dm32Codeplug.Channel(self._io, self, self._root)
            self.vfo_b._read()
            self.tag = self._io.read_u1()
            self._dirty = False


        def _fetch_instances(self):
            pass
            for i in range(len(self.channels)):
                pass
                self.channels[i]._fetch_instances()

            self.vfo_a._fetch_instances()
            self.vfo_b._fetch_instances()


        def _write__seq(self, io=None):
            super(Dm32Codeplug.ChannelBankVfo, self)._write__seq(io)
            for i in range(len(self.channels)):
                pass
                self.channels[i]._write__seq(self._io)

            self._io.write_bytes(self.gap)
            self.vfo_a._write__seq(self._io)
            self.vfo_b._write__seq(self._io)
            self._io.write_u1(self.tag)


        def _check(self):
            if len(self.channels) != 83:
                raise kaitaistruct.ConsistencyError(u"channels", 83, len(self.channels))
            for i in range(len(self.channels)):
                pass
                if self.channels[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"channels", self._root, self.channels[i]._root)
                if self.channels[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"channels", self, self.channels[i]._parent)

            if len(self.gap) != 15:
                raise kaitaistruct.ConsistencyError(u"gap", 15, len(self.gap))
            if self.vfo_a._root != self._root:
                raise kaitaistruct.ConsistencyError(u"vfo_a", self._root, self.vfo_a._root)
            if self.vfo_a._parent != self:
                raise kaitaistruct.ConsistencyError(u"vfo_a", self, self.vfo_a._parent)
            if self.vfo_b._root != self._root:
                raise kaitaistruct.ConsistencyError(u"vfo_b", self._root, self.vfo_b._root)
            if self.vfo_b._parent != self:
                raise kaitaistruct.ConsistencyError(u"vfo_b", self, self.vfo_b._parent)
            self._dirty = False


